    PluginJson tools()const override{return PluginJson::array({tool("widget.show","显示或隐藏桌面小角色。",object({{"visible",{{"type","boolean"}}}},PluginJson::array({"visible"}))),tool("widget.move","缓慢移动到桌面中的相对位置，坐标范围 0 到 1。",object({{"x",{{"type","number"},{"minimum",0},{"maximum",1}}},{"y",{{"type","number"},{"minimum",0},{"maximum",1}}}},PluginJson::array({"x","y"}))),tool("widget.animate","切换一个简单动画意图。",object({{"state",{{"enum",PluginJson::array({"idle","walk","resting","curious","listening","eating"})}}}},PluginJson::array({"state"}))),tool("widget.say","在小角色旁显示一段文字气泡。",object({{"text",{{"type","string"},{"minLength",1},{"maxLength",1000}}},{"seconds",{{"type","number"},{"minimum",1},{"maximum",60}}}},PluginJson::array({"text"}))),tool("widget.status","读取小角色当前动画与位置。",object())});}
